steps.code:
def safe_divide(a, b):
    try:
        result = a / b
    except ZeroDivisionError:
        return "undefined"
    else:
        return round(result, 2)

print(safe_divide(10, 4))
print(safe_divide(1, 0))
try:
    print(safe_divide("10", 2))
except TypeError as err:
    print("TypeError:", type(err).__name__)
print("done")

