tests.code:
try:
    withdraw(10, 20)
except ValueError:
    pass
else:
    assert False, 'withdraw(10, 20) should raise ValueError'

for _bad in (0, -5):
    try:
        withdraw(10, _bad)
    except ValueError:
        pass
    else:
        assert False, f'withdraw(10, {_bad}) should raise ValueError'

steps.solution:
def withdraw(balance, amount):
    if amount <= 0:
        raise ValueError("amount must be positive")
    if amount > balance:
        raise ValueError("insufficient funds")
    return balance - amount

